<?php
declare(strict_types=1);
function process_mapping_csv_safe(string$value):string{return preg_match('/^[=+\-@]/',$value)?"'".$value:$value;}
function process_mapping_export_csv():never{require_permission('reports.export');$processes=process_mapping_processes();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="business-process-catalog-'.date('Ymd').'.csv"');$out=fopen('php://output','wb');fputcsv($out,['Process Code','Process','Category','Value Chain','Status','Version','Instances','Open Exceptions']);foreach($processes as$p){$version=process_mapping_process_version($p);$instances=process_mapping_instances((int)$p['id']);$open=0;foreach($instances as$i)$open+=count(array_filter(process_mapping_exceptions((int)$i['id']),fn($e)=>$e['status']!=='resolved'));fputcsv($out,array_map('process_mapping_csv_safe',[(string)$p['process_code'],(string)$p['process_name'],(string)$p['category_code'],(string)$p['value_chain'],(string)$p['status'],(string)($version['version_number']??''),(string)count($instances),(string)$open]));}fclose($out);exit;}
